  if (n.type === "COMPONENT" || n.type === "FRAME" || n.type === "INSTANCE") {
    info += " | children: " + n.children.map(c => c.name + "(" + c.type + ")").join(", ");
    if (n.fills && n.fills !== figma.mixed) info += " | fills: " + JSON.stringify(n.fills);
  }
  out.push(info);
}
