function dump(n, d) {
  let s = "  ".repeat(d) + n.name + " [" + n.type + "]";
  if (n.type === "TEXT") s += " chars=" + JSON.stringify(n.characters) + " font=" + JSON.stringify(n.fontName) + " size=" + n.fontSize + " fills=" + JSON.stringify(n.fills);
  if ("cornerRadius" in n && n.cornerRadius !== undefined) s += " r=" + n.cornerRadius;
  if (n.fills && n.fills !== figma.mixed && n.type !== "TEXT") s += " fills=" + JSON.stringify(n.fills);
  let lines = [s];
  if ("children" in n) for (const c of n.children) lines = lines.concat(dump(c, d+1));
  return lines;
}
