  const meta=figma.createFrame(); meta.name="Meta"; meta.fills=[]; meta.layoutMode="HORIZONTAL"; meta.itemSpacing=5; meta.counterAxisAlignItems="CENTER";
  meta.primaryAxisSizingMode="AUTO"; meta.counterAxisSizingMode="AUTO";
  const chip=figma.createFrame(); chip.name="Risk"; chip.fills=solid(riskColor); chip.cornerRadius=7;
  chip.paddingLeft=6;chip.paddingRight=6;chip.paddingTop=2;chip.paddingBottom=2;
