  const chipT=await T(risk,8,"Bold",C.white); chip.appendChild(chipT);
  meta.appendChild(chip);
  const pp=await T(participants,8,"Medium",C.text2); meta.appendChild(pp);
  card.appendChild(meta);
  const retRow=figma.createFrame(); retRow.name="Return"; retRow.fills=[]; retRow.layoutMode="HORIZONTAL"; retRow.itemSpacing=3; retRow.counterAxisAlignItems="MAX";
  retRow.primaryAxisSizingMode="AUTO"; retRow.counterAxisSizingMode="AUTO";
  const rv=await T(ret,15,"ExtraBold",C.gain); retRow.appendChild(rv);
  const py=await T("per year",8,"Medium",C.text2); retRow.appendChild(py);
  card.appendChild(retRow);
  const view=figma.createFrame(); view.name="View"; view.fills=solid(C.brand); view.cornerRadius=10;
