// reactions summary
let total=0;
for(const f of frames){
  const nodes=[f,...f.findAll(n=>n.reactions&&n.reactions.length>0)];
  nodes.forEach(n=>{
    n.reactions.forEach(r=>{
      total++;
      const a=r.actions[0];
      const dest=a.destinationId?figma.getNodeById(a.destinationId):null;
      out.push("  "+f.name+" ["+n.name+"] "+r.trigger.type+" -> "+(dest?dest.name:a.type));
    });
  });
}
out.push("TOTAL REACTIONS: "+total);
// components count
const comps=page.findAll(n=>n.type==="COMPONENT");
out.push("COMPONENTS IN WORKSPACE: "+comps.length);
comps.forEach(c=>out.push("  "+c.name));
return out.join("\n");

